const query = $input.first().json.body.query;
const docType = $input.first().json.body.doc_type || 'all';

return [{
  json: {
    query: query,
    doc_type: docType,
    timestamp: new Date().toISOString()
  }
}];

const query = $('Parse User Query').first().json.query;
const searchResults = $input.first().json;

let context = '';
if (searchResults.documents) {
  context = searchResults.documents.map((doc, i) => 
    `[Source ${i+1}: ${doc.doc_id}]
${doc.content}`
  ).join('

---

');
}

const prompt = `You are a Legal Research Assistant. Use the following context to answer the legal question.

CONTEXT:
${context}

QUESTION: ${query}

Provide a comprehensive legal analysis with citations.

DISCLAIMER: This is research assistance only. Consult a licensed attorney.`;

return [{ json: { prompt: prompt, query: query, num_sources: searchResults.documents?.length || 0 } }];

const answer = $input.first().json.message?.content || $input.first().json.choices?.[0]?.message?.content || 'No response generated';
const query = $('Build Legal Prompt').first().json.query;
const numSources = $('Build Legal Prompt').first().json.num_sources;

return [{
  json: {
    query: query,
    answer: answer,
    sources_used: numSources,
    timestamp: new Date().toISOString(),
    model: 'gpt-4o',
    disclaimer: 'This is research assistance only. Consult a licensed attorney.'
  }
}];
